"""Further essays on questions from the project's original conversation."""
ESSAYS = [
dict(slug='obrazovanie-i-dobrota', title='Становится ли человек добрее, когда больше знает?', theme='Образование и совесть',
 lead='Очень хочется верить, что хорошее образование делает мир лучше. Но ведь умный человек тоже может быть жестоким. Чего же не хватает одним знаниям?',
 lens='Христианский взгляд · Ответственность за знание · Школа и литература', art='mental-count', art_title='Дети, которые думают',
 art_text='<p>На картине Богданова-Бельского ученики решают одну задачу. Кто-то уже близок к ответу, кто-то ещё всматривается в доску. У каждого своё лицо, своё усилие. Эта картина здесь — образ школы, в которой за общим делом виден отдельный ребёнок.</p>',
 sections=[
 ('Знание увеличивает наши возможности','''<p>Образование многое меняет. Человек читает более сложные тексты, точнее замечает причинные связи, может проверить расчёт и задать вопрос тому, кто говорит уверенно. Ему становятся доступны занятия, о которых раньше он даже не знал. Это настоящее расширение жизни.</p><p>Но возможность и поступок всё-таки различаются. Можно хорошо понимать чужую слабость и помочь. Можно использовать то же понимание, чтобы обмануть. Поэтому вопрос о нравственном смысле образования возникает внутри самого обучения: ради чего мы учимся и что собираемся делать с полученной силой?</p>'''),
 ('Литература возвращает в задачу человека','''<p>В «Уроках французского» мальчику нужны знания, но ему ещё нужно есть. Учительница замечает то, что легко оставить за пределами урока. Распутин заставляет читателя думать о способе помощи: как поддержать ученика, не унизив его? Одного правильного педагогического слова здесь мало — приходится искать действие.</p><p>В «Недоросле» образование может выглядеть внешней принадлежностью приличного дома. Учителя наняты, занятия существуют, а отношение к людям остаётся жестоким. Смешное у Фонвизина постепенно становится тревожным: что вырастет из обучения, если ребёнок каждый день видит право сильного унижать слабого?</p><p>Эти произведения не дают одинакового рецепта школы. Они помогают поставить один общий вопрос: остаётся ли человек целью всего, что мы делаем, или становится материалом для отметки, репутации и красивого отчёта?</p>'''),
 ('Можно ли записать доброту формулой?','''<p>Иногда хочется представить простую зависимость: больше знаний — больше добра. Для такой формулы пришлось бы сначала договориться, что именно мы измеряем. Число прочитанных книг? Результат экзамена? Готовность прийти на помощь? Уже здесь видно, что речь идёт о разных вещах.</p><p>Это логическое замечание, а не результат психологического исследования. Оно показывает предел слишком быстрого вывода. Высокий балл подтверждает выполнение определённой работы; всю нравственную жизнь человека он не описывает.</p><p>Математическая точность всё же полезна. Она приучает видеть, где есть основание для ответа, где допущение, а где мы просто очень хотим, чтобы получилось именно так. Такая честность нужна и в разговоре о людях.</p>'''),
 ('Чему тогда стоит учить вместе со знанием','''<p>Христианская мысль добавляет к вопросу «что я могу?» вопрос «что происходит с моим ближним?». Хорошее решение должно выдержать встречу с тем, кого оно затронет. Удобно ли оно ему? Не отняли ли у него голос? Не назвали ли мы заботой собственное желание всем распорядиться?</p><p>В школе это начинается с небольших вещей. Можно признать ошибку перед учеником. Можно выслушать ответ до конца. Можно объяснить ещё раз, не делая непонимание поводом для стыда. От таких действий не возникает немедленно совершенное общество. Но у ребёнка появляется опыт отношений, в которых ум и человечность помогают друг другу.</p><p>Наверное, поэтому образование всё-таки даёт надежду. В нём есть возможность передать следующему человеку не только знания, но и привычку обращаться с другим бережно.</p>''')],
 quote='darenie', quote_comment='Присвоить весь успех себе очень легко. Память об учителях, близких и полученной помощи возвращает знание в отношения между людьми.',
 extra_quotes=['pamyat-o-slabosti'], music=[('cello','Негромкая сарабанда Баха сопровождает размышление об учёбе и внимании. Здесь можно просто побыть рядом с прочитанным.')],
 prompt='Достаточно ли образованности, чтобы быть нравственным человеком?', writing='Возьмите один эпизод, в котором герой проявляет знания, и другой, где ему приходится выбирать способ обращения с человеком. Совпадают ли в этих эпизодах ум и доброта? Из этого различия может вырасти ваш собственный тезис.',
 books=[('uroki-frantsuzskogo-dostoinstvo','Валентин Распутин. «Уроки французского»','как помочь ученику и сохранить его достоинство?'),('nedorosl','Денис Фонвизин. «Недоросль»','что происходит с образованием в доме, где привыкли унижать людей?')],
 sources=[('https://ilibrary.ru/text/1098/p.1/index.html','Д. И. Фонвизин. «Недоросль»','Литературная опора; анализ поступков и устройства воспитания.'),('/masterskaya/uroki-frantsuzskogo-dostoinstvo/','Разбор «Уроков французского» и первоисточники','Подробный разговор о помощи и достоинстве ученика.')]),

dict(slug='dobro-i-zhestokost',title='Как защищать добро и не привыкнуть к жестокости',theme='Сопротивление злу',
 lead='Когда видишь несправедливость, хочется, чтобы её наконец остановили. Но что происходит с нами самими, пока мы боремся?',
 lens='Христианская этика · Литературный поступок · Цель и средства',art='truth-pilate',art_title='Истина перед лицом власти',
 art_text='<p>На картине Николая Ге Пилат стоит в ярком свете, Христос — в тени. Их встреча сопровождает разговор об истине и решении человека, у которого есть власть. Художественный свет здесь не равен нравственной правоте.</p>',
 sections=[
 ('Желание остановить зло понятно','''<p>Свидетель чужого унижения не обязан делать вид, что ничего не случилось. Встать рядом с пострадавшим, назвать ложь ложью, добиваться прекращения жестокости — всё это требует сил. Мирное отношение к человеку не означает согласия с тем, что он делает.</p><p>Трудность начинается там, где чувство правоты разрешает уже всё. Мы перестаём спрашивать о цене своих действий, потому что заранее уверены в благой цели. Чужая боль начинает казаться заслуженной. В такой момент особенно нужен вопрос: кого мы сейчас защищаем и что именно прекращаем?</p>'''),
 ('Почему так тяжело читать «После бала»','''<p>Толстой сначала даёт увидеть полковника любящим отцом, красивым участником общего праздника. Утром тот же человек участвует в жестоком наказании. Противоречие нельзя устранить, объявив одну из сцен ненастоящей. Обе принадлежат одному художественному миру.</p><p>Для Ивана Васильевича важно именно узнавание. Насилие совершает не заранее обозначенный чужой злодей. Оно существует рядом с хорошими манерами, нежностью, уважением окружающих. Рассказ заставляет усомниться в привычке оценивать нравственное положение человека по внешней привлекательности его роли.</p><p>Отсюда и неприятный вопрос к себе: какие действия мы перестаём замечать, когда нам нравится тот, кто их совершает? Он требует внимательности даже тогда, когда наш собственный круг считает себя безусловно правым.</p>'''),
 ('Средства входят в результат','''<p>Можно мысленно разделить действие на цель, способ и последствия. Это полезная схема для рассуждения, но в жизни части не изолированы. Если мы добиваемся согласия унижением, унижение уже становится частью созданных отношений. Оно не исчезает после объявления успеха.</p><p>В «Сигнале» Гаршина решающий поступок связан с попыткой спасти людей от последствий чужого гнева. Важно, что внимание возвращается к конкретной опасности. Людей в поезде нельзя превратить в довод спора между обиженным человеком и теми, кого он винит.</p><p>Из этого не получается универсального алгоритма на любую тяжёлую ситуацию. Зато появляется ясный способ проверить рассуждение: названы ли в нём все, кто может пострадать, или кто-то исчез за словами о справедливости?</p>'''),
 ('Сохранить способность остановиться','''<p>Православная мысль о покаянии обращена и к человеку, который защищает правое дело. Признание собственной неправоты не делает добро ненужным. Оно позволяет вовремя увидеть, что выбранное действие уже противоречит тому, ради чего начиналась борьба.</p><p>Поэтому так важен человек, которому можно возразить. Учитель, родитель, руководитель, друг нуждаются не только в поддержке. Им нужен кто-то, чьё «ты сейчас поступаешь жестоко» ещё может быть услышано.</p><p>Сохранить такую возможность трудно. Но, наверное, именно она и помогает сопротивляться злу, не обустраивая его внутри собственных отношений.</p>''')],
 quote='peremena',quote_comment='Нравственный выбор не закреплён за человеком раз и навсегда. Возможность измениться оставляет надежду и требует внимательности к себе.',extra_quotes=['smirenie-protiv-gordosti'],
 music=[('bach','Ария Erbarme dich сопровождает тему раскаяния и милости. Голос звучит без торжества над побеждённым.')],
 prompt='Может ли уверенность в доброй цели сделать человека жестоким?',writing='Начните с поступка, а не с общей оценки героя. Назовите его цель, избранное средство и того, кого затронули последствия. Затем покажите, какую из этих сторон рассказ делает особенно заметной.',
 books=[('posle-bala-uvidet-nasilie','Лев Толстой. «После бала»','зачем читателю нужно увидеть одного человека и на балу, и утром?'),('signal-prekratit-zlo','Всеволод Гаршин. «Сигнал»','как внимание к чужой жизни меняет ход конфликта?')],
 sources=[('/masterskaya/posle-bala-uvidet-nasilie/','«После бала»: разбор и первоисточник','Контраст сцен и перемена восприятия рассказчика.'),('/masterskaya/signal-prekratit-zlo/','«Сигнал»: разбор и первоисточник','Конкретная жизнь перед лицом чужого гнева.'),('https://www.pravmir.ru/o-nasilii/','Митрополит Антоний Сурожский. «О насилии»','Дополнительное авторское размышление; цитаты из этой публикации в святоотеческий корпус не перенесены.')]),

dict(slug='toska-po-miru',title='Чего нам не хватает, когда мы тоскуем по миру',theme='Замысел проекта',
 lead='Иногда кажется, что тоска по миру достигает космических масштабов. Хочется просто жить, читать, разговаривать с близкими. Почему это простое желание оказывается таким большим?',
 lens='Христианская надежда · Дом и близость · Литература как встреча',art='philosophers',art_title='Идти рядом',
 art_text='<p>«Философы» Нестерова возвращают к самому началу проекта. Два человека идут рядом, каждый со своим лицом и своей мыслью. Так может выглядеть разговор: общая дорога оставляет место двум разным людям.</p>',
 sections=[
 ('Мир — и тишина, и связь','''<p>В русском слове «мир» слышится и отсутствие вражды, и всё пространство жизни. Наверное, поэтому тоска по миру не сводится к желанию, чтобы стало тихо. Можно жить в тишине и быть одиноким. Можно молчать, потому что страшно говорить. А хочется такого покоя, в котором не нужно прятать себя.</p><p>Дом, дорога, письмо, голос близкого — совсем небольшие вещи рядом с огромными историческими событиями. Но именно через них человек обычно чувствует, что жизнь ему принадлежит. Литература умеет возвращать этим вещам их настоящий размер.</p>'''),
 ('Книга позволяет задержаться возле чужой жизни','''<p>В «Станционном смотрителе» нельзя до конца восстановить разговор, который уже не состоялся. Пушкин оставляет читателю историю разлуки, отцовского горя и позднего возвращения. Желание всё объяснить встречает предел: судьбу человека нельзя уместить в удобный приговор.</p><p>В «Юшке» люди видят странного, безответного соседа и долго не знают, кому нужна его жизнь. Скрытая забота становится понятна поздно. Платонов меняет наше знание о герое и вместе с ним — значение уже прочитанных сцен.</p><p>В обеих историях читатель учится замечать то, что окружающие пропустили. Этот опыт не гарантирует доброты. Но он даёт возможность остановиться прежде, чем повторить знакомое равнодушное суждение о живом человеке.</p>'''),
 ('Надежда не обязана быть громкой','''<p>Христианская надежда допускает слёзы, растерянность и ожидание. Она не требует от человека каждое утро выглядеть победителем. Иногда надежда сохраняется в очень небольшом действии: ответить на письмо, приготовить еду, прийти к тому, кто остался один.</p><p>У такого действия есть предел. Оно не устраняет всю несправедливость и не возвращает утраченное. Но для человека, к которому пришли, оно всё равно может оказаться важным. Малый размер помощи не равен её отсутствию.</p><p>Поэтому нам нужна точность и в словах о добре. Если мы обещаем слишком много, потом легко решить, что всё было напрасно. Если называем сделанное честно, замечаем настоящее: в этот день одному человеку было чуть менее одиноко.</p>'''),
 ('Зачем тогда сайт о литературе','''<p>Здесь можно читать ради сочинения, а можно задержаться возле вопроса, который экзаменом не заканчивается. Что такое милосердие? Почему трудно простить? Как сохранить своё убеждение и услышать другого? Ответы становятся интереснее, когда рядом оказывается конкретная книга.</p><p>Православная мысль — основа этого разговора. Точные слова духовных авторов помогают не ограничиваться собственным первым впечатлением. А картина и музыка дают паузу, в которой прочитанное можно просто пережить.</p><p>Очень хочется, чтобы у ученика оставалась собственная мысль. Не ещё один выученный правильный абзац, а найденная им связь между словом, поступком и человеком. Ради такой встречи и существует «Узел тоски по миру».</p>''')],
 quote='skorbi',quote_comment='Скрытая от нас скорбь не становится от этого менее настоящей. Эта короткая мысль помогает начать разговор о внимании к человеку.',extra_quotes=['mir-pered-molitvoy'],
 music=[('vigil','«Ныне отпущаеши» Рахманинова сопровождает тему ожидания и покоя. Песнопение сохраняет свой евангельский смысл, а здесь становится музыкальной иллюстрацией к размышлению.')],
 prompt='Почему человеку важно не чувствовать себя одиноким?',writing='Выберите эпизод, в котором присутствие другого что-то меняет. Это может быть поступок, разговор или позднее узнавание чужой заботы. Покажите, что именно изменилось, не обещая, что одна встреча разрешила всю жизнь героя.',
 books=[('yushka-nevidimoe-dobro','Андрей Платонов. «Юшка»','почему значение чужой заботы становится понятно так поздно?'),('smotritel-vozvrashchenie','Александр Пушкин. «Станционный смотритель»','что возвращение способно изменить, а что уже остаётся невозвратимым?')],
 sources=[('/masterskaya/yushka-nevidimoe-dobro/','«Юшка»: разбор и первоисточники','Скрытая забота и позднее узнавание.'),('/masterskaya/smotritel-vozvrashchenie/','«Станционный смотритель»: разбор и первоисточники','Разлука, возвращение и границы читательского суждения.'),('https://tretyakovgallerymagazine.ru/articles/1-2013-38/nesterov-portretist','«Нестеров-портретист»','Материал о художественном контексте картины «Философы».')]),
]
